package com.bananalab.lite;
import android.content.*;import org.json.*;import java.util.*;import java.util.regex.*;
/** Atomic declarative extension package. No Java or new Android permissions. */
final class ModularHub{
 static final class Bundle{
  final JSONObject source;final JSONObject profile;final JavaTextPlan replies;final RuntimeProgram program;final JSONArray panels;
  Bundle(String raw)throws Exception{if(raw.length()>60000)throw new IllegalArgumentException("El paquete admite60KB.");source=new JSONObject(raw);RuntimeProgram.keys(source,"version","profile","replies","behaviors","panels");if(source.getInt("version")!=1)throw new IllegalArgumentException("Versión de paquete inválida.");profile=source.getJSONObject("profile");RuntimeProgram.keys(profile,"text","buttons","spacing","theme","context","projects","jump","gesture","accent","buttonColors","font");AppJavaWorkspace.Settings settings=merge(new AppJavaWorkspace.Settings(),profile);AppJavaWorkspace.validate(settings);replies=JavaTextPlan.read(source.getJSONObject("replies").toString());if(replies.replace)throw new IllegalArgumentException("Los paquetes agregan respuestas, no eliminan todo el chat.");replies.controls();for(JavaTextPlan.Rule rule:replies.rules)if(!rule.operation.equals("equals")||!rule.variable.equals("text"))throw new IllegalArgumentException("El paquete admite respuestas de igualdad normalizada.");program=new RuntimeProgram(source.getJSONObject("behaviors").toString());program.test();panels=source.getJSONArray("panels");if(panels.length()>4)throw new IllegalArgumentException("Hasta cuatro paneles por paquete.");Set<String> names=new HashSet<>();for(int i=0;i<panels.length();i++){JSONObject panel=panels.getJSONObject(i);RuntimeProgram.keys(panel,"name","buttons");String name=panel.getString("name");if(name.trim().length()<2||name.length()>35||!names.add(name))throw new IllegalArgumentException("Nombre de panel inválido.");JSONArray buttons=panel.getJSONArray("buttons");if(buttons.length()<1||buttons.length()>6)throw new IllegalArgumentException("Cada panel admite hasta seis herramientas.");for(int j=0;j<buttons.length();j++){JSONObject b=buttons.getJSONObject(j);RuntimeProgram.keys(b,"label","command");if(b.getString("label").trim().isEmpty()||b.getString("label").length()>35||!allowed(b.getString("command")))throw new IllegalArgumentException("Etiqueta u orden no admitida en el panel.");}}}
 }
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-modular-hub",0);}
 static volatile Bundle active;static int loaded=-1;static AppJavaWorkspace.Settings cachedBase,cachedView;static Bundle cachedBundle;
 static JSONObject empty()throws Exception{return new JSONObject().put("version",1).put("profile",new JSONObject()).put("replies",new JavaTextPlan().json()).put("behaviors",new JSONObject(RuntimeModules.EMPTY)).put("panels",new JSONArray());}
 static String code(Context c)throws Exception{return prefs(c).getString("active",empty().toString());}
 static AppJavaWorkspace.Settings merge(AppJavaWorkspace.Settings base,JSONObject p)throws Exception{JSONObject json=base.json();Iterator<String> keys=p.keys();while(keys.hasNext()){String key=keys.next();json.put(key,p.get(key));}return AppJavaWorkspace.Settings.read(json);}
 static AppJavaWorkspace.Settings view(){Bundle b=active;AppJavaWorkspace.Settings base=AppJavaWorkspace.live;if(b==null||b.profile.length()==0)return base;synchronized(ModularHub.class){if(cachedBase!=base||cachedBundle!=b){try{cachedView=merge(base,b.profile);}catch(Exception e){cachedView=base;}cachedBase=base;cachedBundle=b;}return cachedView;}}
 static int background(){return new int[]{0xff141922,0xff142638,0xff182c25,0xff291d36}[view().theme];}
 static synchronized void restore(Context c){int rev=prefs(c).getInt("revision",0);if(loaded==rev)return;try{active=new Bundle(code(c));loaded=rev;}catch(Exception e){active=null;loaded=rev;prefs(c).edit().putString("error","Paquete inválido: usé el núcleo base.").apply();}}
 static boolean allowed(String command){String q=ChatLanguage.normalize(command);return command.length()<=300&&q.matches("(?s)^(?:mis personajes|mis escenas|mostrame el plan|ver borrador|estado del aprendizaje|estado de banana modular|crea .+|agrega .+|continua con .+|pone .+|versiones de banana modular|como cambio la funcion del salto|como edito un metodo java)$")&&!command.contains(";")&&!command.contains("\n");}
 static JSONObject copy(Context c)throws Exception{return new JSONObject(code(c));}
 static void editProfile(JSONObject root,String clause)throws Exception{AppJavaWorkspace.Settings old=merge(AppJavaWorkspace.live,root.getJSONObject("profile"));AppJavaChat.Plan plan=AppJavaChat.plan(clause,old);if(!plan.handled)throw new IllegalArgumentException("No entendí el ajuste: "+clause);JSONObject previous=old.json(),next=plan.settings.json(),profile=root.getJSONObject("profile");Iterator<String> keys=next.keys();while(keys.hasNext()){String key=keys.next();if(!next.get(key).toString().equals(previous.optString(key,"{}")))profile.put(key,next.get(key));}}
 static String[] clauses(String text){List<String> out=new ArrayList<>();boolean quoted=false,escaped=false;int start=0;for(int i=0;i<text.length();i++){char ch=text.charAt(i);if(escaped){escaped=false;continue;}if(quoted&&ch=='\\'){escaped=true;continue;}if(ch=='"')quoted=!quoted;else if(ch==';'&&!quoted){out.add(text.substring(start,i));start=i+1;}}if(quoted)throw new IllegalArgumentException("Falta cerrar una comilla.");out.add(text.substring(start));return out.toArray(new String[0]);}
 static synchronized String prepare(Context c,String instructions)throws Exception{JSONObject root=copy(c);String[] parts=clauses(instructions);if(parts.length>8)throw new IllegalArgumentException("Hasta ocho cambios por paquete.");for(String part:parts){String q=ChatLanguage.normalize(part);Matcher response=Pattern.compile("(?isu)^\\s*respuesta ("+JavaTextPlan.LIT+")\\s*=>\\s*("+JavaTextPlan.LIT+")\\s*$").matcher(part);Matcher behavior=Pattern.compile("^comportamiento ([a-z][a-z ]{2,30}): (.+)$").matcher(part.trim().toLowerCase(Locale.ROOT));Matcher tool=Pattern.compile("(?isu)^\\s*herramienta ("+JavaTextPlan.LIT+") con ("+JavaTextPlan.LIT+") para ("+JavaTextPlan.LIT+")\\s*$").matcher(part);
   if(response.matches()){JavaTextPlan p=JavaTextPlan.read(root.getJSONObject("replies").toString());p.add("equals",JavaTextPlan.decode(response.group(1)),JavaTextPlan.decode(response.group(2)));root.put("replies",p.json());}
   else if(behavior.matches()){String name=ChatLanguage.normalize(behavior.group(1));List<String> moves=JavaChat.moves(ChatLanguage.normalize(behavior.group(2)));if(moves.isEmpty())throw new IllegalArgumentException("El comportamiento necesita movimientos.");String pattern="{actor} "+name,id="hub_"+Integer.toHexString(name.hashCode());JSONArray steps=new JSONArray(),expected=new JSONArray();for(String op:moves){steps.put(RuntimeModules.step(op,"actor",""));expected.put(op);}JSONObject module=RuntimeModules.module(id,pattern,steps,expected),behaviors=root.getJSONObject("behaviors");JSONArray all=behaviors.getJSONArray("modules"),next=new JSONArray();for(int i=0;i<all.length();i++)if(!all.getJSONObject(i).getString("id").equals(id))next.put(all.getJSONObject(i));next.put(module);behaviors.put("modules",next);}
   else if(tool.matches()){String name=JavaTextPlan.decode(tool.group(1)),label=JavaTextPlan.decode(tool.group(2)),command=JavaTextPlan.decode(tool.group(3));JSONArray panels=root.getJSONArray("panels");JSONObject found=null;for(int i=0;i<panels.length();i++)if(panels.getJSONObject(i).getString("name").equals(name))found=panels.getJSONObject(i);if(found==null){found=new JSONObject().put("name",name).put("buttons",new JSONArray());panels.put(found);}JSONArray buttons=found.getJSONArray("buttons"),next=new JSONArray();for(int i=0;i<buttons.length();i++)if(!buttons.getJSONObject(i).getString("label").equals(label))next.put(buttons.getJSONObject(i));next.put(new JSONObject().put("label",label).put("command",command));found.put("buttons",next);}
   else editProfile(root,part.trim());}
  Bundle b=new Bundle(root.toString());String previous=code(c);int revision=prefs(c).getInt("revision",0);JSONObject draft=new JSONObject().put("source",b.source).put("base",revision).put("priorHash",JavaMethodEditor.hash(previous));if(!prefs(c).edit().putString("draft",draft.toString()).commit())throw new java.io.IOException("No pude guardar el paquete.");return "Preparé y probé el paquete completo: interfaz, respuestas, comportamientos y paneles. Ninguna parte está activa todavía.\nDecí ‘ver actualizacion modular’, ‘aplica actualizacion modular’ o ‘descarta actualizacion modular’.";
 }
 static JSONArray history(Context c)throws Exception{return new JSONArray(prefs(c).getString("history","[]"));}
 static JSONArray archived(Context c)throws Exception{JSONArray h=history(c),next=new JSONArray();for(int i=Math.max(0,h.length()-4);i<h.length();i++)next.put(h.getJSONObject(i));next.put(new JSONObject().put("revision",prefs(c).getInt("revision",0)).put("source",new JSONObject(code(c))));return next;}
 static synchronized String apply(Context c)throws Exception{String raw=prefs(c).getString("draft","");if(raw.isEmpty())return "No hay un paquete pendiente.";JSONObject d=new JSONObject(raw);int rev=prefs(c).getInt("revision",0);if(d.getInt("base")!=rev||!d.getString("priorHash").equals(JavaMethodEditor.hash(code(c))))throw new IllegalArgumentException("La base cambió; prepará el paquete de nuevo.");Bundle b=new Bundle(d.getJSONObject("source").toString());if(!prefs(c).edit().putString("history",archived(c).toString()).putString("active",b.source.toString()).putInt("revision",rev+1).remove("draft").remove("error").commit())throw new java.io.IOException("No pude activar el paquete.");active=b;loaded=rev+1;return "Listo. Activé todo el paquete en esta instalación, sin otro APK. Abrí ‘mis herramientas modulares’ para ver tus paneles. Podés decir ‘deshace actualizacion modular’.";}
 static synchronized String undo(Context c)throws Exception{JSONArray h=history(c);if(h.length()==0)return "No hay un paquete anterior.";JSONObject last=h.getJSONObject(h.length()-1);Bundle b=new Bundle(last.getJSONObject("source").toString());JSONArray kept=new JSONArray();for(int i=0;i<h.length()-1;i++)kept.put(h.getJSONObject(i));int revision=prefs(c).getInt("revision",0)+1;if(!prefs(c).edit().putString("active",b.source.toString()).putString("history",kept.toString()).putInt("revision",revision).remove("draft").commit())throw new java.io.IOException("No pude recuperar el paquete.");active=b;loaded=revision;return "Recuperé el paquete anterior: interfaz, respuestas, comportamientos y paneles juntos. Tus escenas se conservan.";}
 static String reply(String input){Bundle b=active;if(b==null)return null;String text=ChatLanguage.normalize(input).replaceFirst("^banana ","");for(JavaTextPlan.Rule r:b.replies.rules)if(r.operation.equals("equals")&&text.equals(r.trigger))return r.reply;return null;}
 static BananaEngine.Result execute(Context c,String message)throws Exception{Bundle b=active;if(b==null||b.program.modules.isEmpty())return null;String snap=MobilePlan.snapshot(c);SceneDraft base=MobileCore.scene(c);RuntimeProgram.Result result=b.program.run(message,base);if(!result.matched)return null;if(result.scene==null)return MobileCore.say(c,result.error,"modular");synchronized(ModularHub.class){if(b!=active||!snap.equals(MobilePlan.snapshot(c)))return MobileCore.say(c,"Cambió el paquete o la escena; repetí el pedido.","modular");CreatorSession owner=CreatorMemory.load(c);CreatorSession.Result update=owner.update(result.scene,owner.pending!=null,"Apliqué el comportamiento modular "+result.module,false);CreatorMemory.save(c,owner,update.commit);BananaEngine.Result out=MobileCore.say(c,update.text,"modular");out.changed=update.commit!=null;return out;}}
 static BananaEngine.Result handle(Context c,String message)throws Exception{String q=ChatLanguage.normalize(message);try{if(q.startsWith("prepara actualizacion modular")){int colon=message.indexOf(':');if(colon<0||!ChatLanguage.normalize(message.substring(0,colon)).equals("prepara actualizacion modular"))throw new IllegalArgumentException("Usá prepara actualizacion modular: y separá cambios con punto y coma.");return MobileCore.say(c,prepare(c,message.substring(colon+1)),"app_ajuste");}if(q.equals("aplica actualizacion modular"))return MobileCore.say(c,apply(c),"app_ajuste");if(q.equals("deshace actualizacion modular"))return MobileCore.say(c,undo(c),"app_ajuste");if(q.equals("descarta actualizacion modular")){if(!prefs(c).edit().remove("draft").commit())throw new java.io.IOException("No pude descartar el paquete.");return MobileCore.say(c,"Descarté el paquete pendiente.","app_ajuste");}if(q.equals("ver actualizacion modular"))return MobileCore.say(c,prefs(c).getString("draft","No hay un paquete pendiente."),"app_ajuste");if(q.equals("reinicia banana modular")){if(!prefs(c).edit().clear().commit())throw new java.io.IOException("No pude reiniciar los módulos.");active=null;loaded=-1;restore(c);return MobileCore.say(c,"Restauré los módulos base. Tus escenas se conservan.","app_ajuste");}if(q.equals("mis herramientas modulares"))return MobileCore.say(c,"Abrí tus herramientas modulares.","modular_panels");if(q.matches("estado de banana modular|versiones de banana modular"))return MobileCore.say(c,"Banana modular · revisión "+prefs(c).getInt("revision",0)+"\nPaquetes anteriores: "+history(c).length()+"\nPerfil, respuestas, hasta16 comportamientos y cuatro paneles. Los valores del paquete prevalecen sobre los ajustes Java mientras estén definidos en el perfil.\nNo reescribe toda la app ni agrega permisos.\n"+prefs(c).getString("error",""),"app_ajuste");if(q.equals("como cambio banana sin reinstalar"))return MobileCore.say(c,"Prepará un paquete por chat:\nprepara actualizacion modular: pone el tema de la app violeta; respuesta \"hola taller\" => \"Taller listo\"; comportamiento fiesta: salta y aplaude; herramienta \"Estudio\" con \"Personajes\" para \"mis personajes\"\nDespués: aplica actualizacion modular. Para usarlo: Fito fiesta.\nLa base fija sigue instalada; estos módulos de datos se actualizan sin otro APK.","app_ajuste");}catch(Exception e){return MobileCore.say(c,"No activé un paquete nuevo. "+e.getMessage(),"app_ajuste");}return execute(c,message);}
}
